function [u,balancing] = furuta_lqr_rev11_step(x,active)
%#codegen
% Generated by lm_export_step: observer + energy swing-up + LQR (comparison-baseline plant).
persistent xh c1 c2 bal home iint
x=double(x(:)); x(2)=x(2)-0.048345620280242932; u=0; balancing=false;
if isempty(xh) || ~active
    xh=[x(1);x(2);0;0]; c1=0; c2=0; bal=false; home=0; iint=0;
    if ~active, u=0; balancing=false; return; end
else
    xp=lmRk4(xh,c2);
    e=[atan2(sin(x(1)-xp(1)),cos(x(1)-xp(1))); atan2(sin(x(2)-xp(2)),cos(x(2)-xp(2)))];
    xh=xp+[0.99866984697794248 3.8427298360179248e-06;0.0002968417327093506 0.97846932205173553;96.90171018870862 -0.0005697298555855185;1.4340377072411821 93.835861394423489]*e;
end
xf=lmRk4(xh,c1);
th=atan2(sin(xf(2)),cos(xf(2))); w=xf(4); v=xf(3);
cap=abs(th)<0.3490658503988659 && abs(w)<4.5;
if cap && ~bal, home=xf(1); end
bal=(bal && abs(th)<0.69813170079773179) || cap;
if ~bal
    iint=0;
    E=.5*0.00033061674707744574*w^2+0.026457179177278859*(cos(th)-1);
    d=sign(w*cos(th)); if d==0, d=1; end
    u=600*E*d;
    if (E+2*0.026457179177278859)<0.001 && abs(th)>pi/2
        u=-sign(sin(th)); if u==0, u=-1; end
    end
    over=max(0,(abs(v)-10)/(4));
    if sign(u)==sign(v), u=u*max(0,1-over); end
else
    z=[max(-0.59999999999999998,min(0.59999999999999998,xf(1)-home)); th; v; w];
    ub=[1.4135430113489478 25.759466767840607 0.83445444113066702 2.8623470254068155]*z;
    if abs(v)>13.5 && sign(ub)==sign(v), ub=0; end
    u=ub+0*tanh(v/0.050000000000000003);
end
u=max(-1,min(1,u));
if ~bal && u~=0 && sign(u)~=sign(v) && abs(v)>1, u=sign(u)*min(abs(u),0); end
if bal && u~=0 && sign(u)~=sign(v) && abs(v)>4, u=sign(u)*min(abs(u),0.33000000000000002); end
u=round(u*150)/150;
u=u(1); c2=c1; c1=u; balancing=logical(bal);
end

function x=lmRk4(x,a)
tau=3.1500000000000004*a; h=0.002;
for i=1:5
    k1=f(x); k2=f(x+h/2*k1); k3=f(x+h/2*k2); k4=f(x+h*k3);
    x=x+h/6*(k1+2*k2+2*k3+k4);
end
    function y=f(z)
        s=sin(z(2)); c=cos(z(2)); vv=z(3); ww=z(4);
        dd=0.021999999999999999+0.00033011920828760312*s^2; b=0.00016504592968264242*c;
        ff=tau-2*0.00033011920828760312*s*c*vv*ww+0.00016504592968264242*s*ww^2-0.12*vv-0.40000000000000002*sign(vv);
        gg=0.00033011920828760312*s*c*vv^2-0.0001*ww+0.026457179177278859*s;
        dt=dd*0.00033061674707744574-b^2;
        y=[z(3);z(4);(0.00033061674707744574*ff-b*gg)/dt;(dd*gg-b*ff)/dt];
    end
end
